class Repo:
    def __init__(self, local, remote):
        self.local = local
        self.remote = remote
        self.remote_ref = list(local)

    def fetch(self):
        self.remote_ref = list(self.remote)
        return f"fetch: remote-tracking actualizado a {len(self.remote_ref)} commits"

    def merge_remote(self):
        new = [c for c in self.remote_ref if c not in self.local]
        self.local.extend(new)
        return f"merge: {len(new)} commit(s) añadidos -> {self.local}"

    def pull(self):
        self.fetch()
        return self.merge_remote()


repo = Repo(local=["c1", "c2"], remote=["c1", "c2", "c3", "c4"])
print(repo.fetch())
print("local tras fetch:", repo.local)
print(repo.pull())
